N = 61
count = 0
for a in range(1, N + 1):
    for b in range(1, N + 1):
        for c in range(1, N + 1):
            for d in range(1, N + 1):
                # Calculate (a^2 + b^2 + c^3 - d^3) mod 61

                # Use modular arithmetic properties to prevent overflow, although 61 is small.
                # Python handles large integers, so direct calculation is fine too.

                val = (a**2 + b**2 + c**3 - d**3)

                if val % N == 0:
                    count += 1

print(f"Total number of solutions (N): {count}")
